.now-gate { display: inline-block; margin-left: 8px; padding: 1px 8px; border-radius: var(--radius-xs); font-size: var(--t-small); font-weight: 700; letter-spacing: .02em; color: var(--on-dark); background: var(--st-n-ink); vertical-align: 1px; }
.now-gate.is-r { background: var(--st-r); }
.now-gate.is-a { background: var(--st-a); }
.now-gate.is-w { background: var(--st-w); }
.now-gate.is-g { background: var(--st-g); }
.now-day { margin-top: 10px; }
.now-dh { font-size: var(--t-small); font-weight: 700; color: var(--ink); margin: 0 0 4px; }
.now-day.is-today .now-dh { color: var(--brand); }
.now-more { margin-top: 6px; }

/* A PROJECT'S TABS FIT A PHONE (26 October — four tabs and More; 27 October Plan among them, six): the neutral totals
   step aside there and only the abnormal stays, red and in words ("4 late"); the totals are on the pages themselves */
@media (max-width: 719px) {
  .nv-tabs { padding: 0 4px; gap: 0; }
  .nv-tab { padding: 0 clamp(3px, 1vw, 8px); }
  .nv-tab-total, .nv-tab-dot { display: none; }
}

/* A machine on its line (line/LineMachineScreen) — gone from the line */
.lmc-gone .sub { margin-top: var(--space-5); }
.lmc-gone .btn { margin-top: var(--space-3); }
.lp-up { margin: var(--space-1) 0 var(--space-2); }
/* where am I (27 October) — a machine's name opens its page; a project's machine opens it on its line; a line's card says Open */
.pl-machine-name { color: var(--brand); text-decoration: none; }
.pl-machine-name:hover b { text-decoration: underline; }
.mpg-line { margin: var(--space-1) 0 0; }
.fac-card-go { margin-top: var(--space-1); color: var(--brand); font-weight: 600; font-size: var(--t-detail); }
/* machines, simply (27 October) — the Factory's Machines tab and a project's list */
.fmc-n { color: var(--muted); font-weight: 700; margin-right: var(--space-1); }
.pms-add { margin-top: var(--space-4); }
.pms-status { display: inline-block; margin-left: var(--space-1); padding: 0 var(--space-2); border-radius: var(--radius-pill); font-size: var(--t-detail); font-weight: 600; border: 1px solid var(--line); color: var(--ink-2); }
.pms-status.is-g { color: var(--st-g); border-color: var(--st-g); }

/* THE FACTORY'S BOARD (27 October — "which line needs me?"): a line's state in a word and its colour, its worst thing */
.fac-card.is-r { border-left: 4px solid var(--st-r); }
.fac-card.is-a { border-left: 4px solid var(--st-a); }
.fac-card-state { font-size: var(--t-detail); font-weight: 700; }
.fac-card-state.is-r { color: var(--st-r); }
.fac-card-state.is-a { color: var(--st-a); }
.fac-card-state.is-g { color: var(--st-g); font-weight: 600; }
.fac-card-worst { font-size: var(--t-detail); color: var(--ink); }
.fac-card-worst.is-r { color: var(--st-r); }
.pl-stops-li { display: flex; flex-direction: column; gap: var(--space-1); }
.pl-stops-li .pl-time { align-self: flex-start; }

/* THE DAY IN THE JOURNEY (27 October, "fold it"): the day's verdict and its update one line under the Journey's range */
.jn-oneday { display: grid; gap: 14px; margin-top: 6px; }
.dy-jn-head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; justify-content: space-between; }
.dy-jn-head > :first-child { flex: 1 1 280px; min-width: 0; margin: 0; }

/* THE WAY BACK (27 October): a page below a tab says the list it sits under, one tap up — "‹ Machines" */
.part-back { display: inline-flex; align-items: center; gap: 4px; margin: 0 0 8px; padding: 6px 10px 6px 6px; min-height: 36px;
  border-radius: var(--radius-sm); font-weight: 600; font-size: var(--t-body); color: var(--brand); text-decoration: none; background: color-mix(in srgb, var(--brand) 9%, transparent); }
.part-back:hover, .part-back:focus-visible { text-decoration: underline; }
